function show(i){cur=i;bs.forEach(function(b,j){b.setAttribute('aria-pressed',j==i?'true':'false')});img.src=A(bs[i].dataset.img);img.className=bs[i].dataset.wide?'wide':''}
function stop(){clearInterval(auto)}
